-- Application-owned data tables, linked to the game-aware catalog.
--
-- Schema only: this migration does not read, copy, or alter production SQLite.
-- GENERATED BY DEFAULT identities allow a later audited importer to preserve
-- legacy integer IDs. Legacy provider IDs and display labels remain alongside
-- optional normalized relationships so unresolved rows are never discarded.

CREATE TABLE app.people (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT people_name_nonempty CHECK (btrim(name) <> '')
);

-- SQLite NOCASE uniqueness is represented by a normalized PostgreSQL index.
CREATE UNIQUE INDEX app_people_name_normalized_uq
    ON app.people (lower(btrim(name)));

CREATE TABLE app.users (
    username TEXT PRIMARY KEY,
    password_hash TEXT NOT NULL,
    is_admin BOOLEAN NOT NULL DEFAULT TRUE,
    role TEXT NOT NULL DEFAULT 'admin',
    is_superadmin BOOLEAN NOT NULL DEFAULT FALSE,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_login_at TIMESTAMPTZ,
    person_id BIGINT,
    CONSTRAINT users_username_nonempty CHECK (btrim(username) <> ''),
    CONSTRAINT users_password_hash_nonempty CHECK (btrim(password_hash) <> ''),
    CONSTRAINT users_person_fk
        FOREIGN KEY (person_id)
        REFERENCES app.people(id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX app_users_username_normalized_uq
    ON app.users (lower(btrim(username)));

-- A person may be the default collection for at most one login. Unlinked
-- service/vendor accounts remain valid, matching the SQLite partial index.
CREATE UNIQUE INDEX app_users_person_id_unique
    ON app.users (person_id)
    WHERE person_id IS NOT NULL;

CREATE TABLE app.login_attempts (
    key TEXT PRIMARY KEY,
    first_attempt DOUBLE PRECISION NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    blocked_until DOUBLE PRECISION NOT NULL DEFAULT 0,
    CONSTRAINT login_attempts_key_nonempty CHECK (btrim(key) <> ''),
    CONSTRAINT login_attempts_attempts_nonnegative CHECK (attempts >= 0)
);

COMMENT ON COLUMN app.login_attempts.first_attempt IS
    'Unix epoch seconds, matching the legacy SQLite rate-limit representation.';
COMMENT ON COLUMN app.login_attempts.blocked_until IS
    'Unix epoch seconds, matching the legacy SQLite rate-limit representation.';

CREATE TABLE app.app_state (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    CONSTRAINT app_state_key_nonempty CHECK (btrim(key) <> '')
);

-- These are application one-time data-migration markers, not SQL schema
-- migrations (those are tracked in public.cardscanner_schema_migrations).
CREATE TABLE app.app_migrations (
    name TEXT PRIMARY KEY,
    applied_at TEXT NOT NULL,
    CONSTRAINT app_migrations_name_nonempty CHECK (btrim(name) <> '')
);

CREATE TABLE app.decklists (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id TEXT NOT NULL DEFAULT 'mtg',
    name TEXT NOT NULL,
    source TEXT NOT NULL DEFAULT 'manual',
    source_url TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    tags_json JSONB NOT NULL DEFAULT '[]'::JSONB,
    person_id BIGINT,
    person_name TEXT,
    cover_filename TEXT,
    cover_scryfall_id TEXT,
    cover_printing_id BIGINT,
    CONSTRAINT decklists_game_fk
        FOREIGN KEY (game_id)
        REFERENCES catalog.games(game_id) ON DELETE RESTRICT,
    CONSTRAINT decklists_person_fk
        FOREIGN KEY (person_id)
        REFERENCES app.people(id) ON DELETE SET NULL,
    CONSTRAINT decklists_cover_printing_game_fk
        FOREIGN KEY (cover_printing_id, game_id)
        REFERENCES catalog.printings(printing_id, game_id)
        ON DELETE SET NULL (cover_printing_id),
    CONSTRAINT decklists_name_nonempty CHECK (btrim(name) <> ''),
    CONSTRAINT decklists_source_nonempty CHECK (btrim(source) <> ''),
    CONSTRAINT decklists_tags_array CHECK (jsonb_typeof(tags_json) = 'array'),
    CONSTRAINT decklists_id_game_uq UNIQUE (id, game_id)
);

CREATE INDEX app_decklists_game_person_idx
    ON app.decklists (game_id, person_id)
    WHERE person_id IS NOT NULL;
CREATE INDEX app_decklists_name_idx
    ON app.decklists (game_id, lower(btrim(name)));

CREATE TABLE app.deck_cards (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    deck_id BIGINT NOT NULL,
    game_id TEXT NOT NULL DEFAULT 'mtg',
    name TEXT NOT NULL,
    quantity INTEGER NOT NULL DEFAULT 1,
    scryfall_id TEXT,
    set_code TEXT,
    collector_number TEXT,
    category TEXT,
    finish TEXT NOT NULL DEFAULT 'normal',
    tcgplayer_id TEXT,
    role_tags_json JSONB NOT NULL DEFAULT '[]'::JSONB,
    any_printing BOOLEAN NOT NULL DEFAULT FALSE,
    card_id BIGINT,
    printing_id BIGINT,
    CONSTRAINT deck_cards_deck_game_fk
        FOREIGN KEY (deck_id, game_id)
        REFERENCES app.decklists(id, game_id) ON DELETE CASCADE,
    CONSTRAINT deck_cards_card_game_fk
        FOREIGN KEY (card_id, game_id)
        REFERENCES catalog.cards(card_id, game_id)
        ON DELETE SET NULL (card_id),
    CONSTRAINT deck_cards_printing_game_fk
        FOREIGN KEY (printing_id, game_id)
        REFERENCES catalog.printings(printing_id, game_id)
        ON DELETE SET NULL (printing_id),
    CONSTRAINT deck_cards_name_nonempty CHECK (btrim(name) <> ''),
    CONSTRAINT deck_cards_quantity_positive CHECK (quantity > 0),
    CONSTRAINT deck_cards_role_tags_array CHECK (jsonb_typeof(role_tags_json) = 'array')
);

CREATE INDEX app_deck_cards_deck_idx
    ON app.deck_cards (deck_id);
CREATE INDEX app_deck_cards_game_name_idx
    ON app.deck_cards (game_id, lower(btrim(name)));
CREATE INDEX app_deck_cards_card_idx
    ON app.deck_cards (game_id, card_id)
    WHERE card_id IS NOT NULL;
CREATE INDEX app_deck_cards_scryfall_idx
    ON app.deck_cards (scryfall_id)
    WHERE scryfall_id IS NOT NULL;

CREATE TABLE app.inventory (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id TEXT NOT NULL DEFAULT 'mtg',
    card_id BIGINT,
    printing_id BIGINT,
    scryfall_id TEXT,
    name TEXT NOT NULL,
    set_code TEXT,
    rarity TEXT,
    price TEXT DEFAULT '0.00',
    scan_time TIMESTAMPTZ NOT NULL DEFAULT now(),
    quantity INTEGER NOT NULL DEFAULT 1,
    owner TEXT NOT NULL DEFAULT 'Me',
    person_id BIGINT,
    finish TEXT NOT NULL DEFAULT 'normal',
    collector_number TEXT,
    tcgplayer_id TEXT,
    location TEXT NOT NULL DEFAULT 'Free',
    deck_id BIGINT,
    for_vending BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT inventory_game_fk
        FOREIGN KEY (game_id)
        REFERENCES catalog.games(game_id) ON DELETE RESTRICT,
    CONSTRAINT inventory_card_game_fk
        FOREIGN KEY (card_id, game_id)
        REFERENCES catalog.cards(card_id, game_id)
        ON DELETE SET NULL (card_id),
    CONSTRAINT inventory_printing_game_fk
        FOREIGN KEY (printing_id, game_id)
        REFERENCES catalog.printings(printing_id, game_id)
        ON DELETE SET NULL (printing_id),
    CONSTRAINT inventory_person_fk
        FOREIGN KEY (person_id)
        REFERENCES app.people(id) ON DELETE SET NULL,
    CONSTRAINT inventory_deck_game_fk
        FOREIGN KEY (deck_id, game_id)
        REFERENCES app.decklists(id, game_id)
        ON DELETE SET NULL (deck_id),
    CONSTRAINT inventory_name_nonempty CHECK (btrim(name) <> ''),
    CONSTRAINT inventory_owner_nonempty CHECK (btrim(owner) <> ''),
    CONSTRAINT inventory_quantity_positive CHECK (quantity > 0),
    CONSTRAINT inventory_finish_nonempty CHECK (btrim(finish) <> ''),
    CONSTRAINT inventory_location_nonempty CHECK (btrim(location) <> '')
);

CREATE INDEX app_inventory_game_name_idx
    ON app.inventory (game_id, lower(btrim(name)));
CREATE INDEX app_inventory_person_idx
    ON app.inventory (game_id, person_id)
    WHERE person_id IS NOT NULL;
CREATE INDEX app_inventory_card_idx
    ON app.inventory (game_id, card_id)
    WHERE card_id IS NOT NULL;
CREATE INDEX app_inventory_scryfall_idx
    ON app.inventory (scryfall_id)
    WHERE scryfall_id IS NOT NULL;
CREATE INDEX app_inventory_tcgplayer_idx
    ON app.inventory (game_id, tcgplayer_id)
    WHERE tcgplayer_id IS NOT NULL;
CREATE INDEX app_inventory_finish_idx
    ON app.inventory (game_id, finish);
CREATE INDEX app_inventory_location_idx
    ON app.inventory (game_id, lower(btrim(location)));
CREATE INDEX app_inventory_deck_idx
    ON app.inventory (deck_id)
    WHERE deck_id IS NOT NULL;
CREATE INDEX app_inventory_for_vending_idx
    ON app.inventory (game_id, for_vending);

-- A scan-log row is an idempotency tombstone. row_id intentionally has no FK:
-- deleting an inventory row must not make a retried scan count as new.
CREATE TABLE app.scan_log (
    scan_id TEXT PRIMARY KEY,
    game_id TEXT NOT NULL DEFAULT 'mtg',
    row_id BIGINT,
    quantity INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT scan_log_game_fk
        FOREIGN KEY (game_id)
        REFERENCES catalog.games(game_id) ON DELETE RESTRICT,
    CONSTRAINT scan_log_id_nonempty CHECK (btrim(scan_id) <> '')
);

CREATE INDEX app_scan_log_created_idx
    ON app.scan_log (created_at DESC);

COMMENT ON TABLE app.inventory IS
    'Physical owned copies. person_id and printing_id are optional normalized links; owner and provider IDs retain legacy values during catalog resolution.';
COMMENT ON COLUMN app.inventory.owner IS
    'Legacy/display owner label retained for lossless import and compatibility; person_id is the normalized relationship when resolved.';
COMMENT ON COLUMN app.inventory.price IS
    'Legacy price text retained without lossy numeric coercion; current market pricing is managed separately.';
COMMENT ON TABLE app.scan_log IS
    'Idempotency records for scanner retries. row_id intentionally is not a foreign key to app.inventory.';
COMMENT ON TABLE app.decklists IS
    'User-owned decklists. person_name and cover_scryfall_id retain legacy source values beside optional normalized links.';
COMMENT ON TABLE app.deck_cards IS
    'Deck requirements. Unresolved provider IDs and unrecognized cards may remain without a catalog printing link.';
